// v2.0: Config wird jetzt live aus HA gelesen.
// Dieser Node dient nur noch als Fallback falls HA States nicht verfügbar.
let config = global.get('smart_charging_config') || {};

config = {
    enabled: true,
    min_charge_current: config.min_charge_current || 7,
    max_charge_current: config.max_charge_current || 32,
    phases: config.phases || 3,
    min_battery_soc: config.min_battery_soc || 95,
    car_target_soc: config.car_target_soc || 80,
    last_update: new Date().toISOString()
};

global.set('smart_charging_config', config);
msg.payload = config;
return msg;

if (msg.data && msg.data.entity_id) {
    msg.payload = {
        entity: msg.data.entity_id,
        value: msg.payload,
        unit: msg.data.new_state ? msg.data.new_state.attributes.unit_of_measurement : ''
    };
}
return msg;

// Hole alle aktuellen States aus Home Assistant
const entities = [
    'sensor.rct_power_storage_grid_power',
    'sensor.rct_power_storage_battery_state_of_charge',
    'sensor.rct_power_storage_battery_power',
    'sensor.rct_power_storage_inverter_ac_power',
    'sensor.rct_power_storage_consumer_power',
    'sensor.easee_home_power',
    'sensor.easee_home_maximum_allowed_charge_current',
    'binary_sensor.easee_home_charging',
    'sensor.zoe_battery',
    'sensor.zoe_plug_state',
    'sensor.zoe_charge_state'
];

// Speichere den aktuellen State
let sensorData = global.get('sensor_data') || {};

// Update den State für diese Entity
if (msg.data && msg.data.entity_id) {
    sensorData[msg.data.entity_id] = {
        state: msg.payload,
        attributes: msg.data.new_state ? msg.data.new_state.attributes : {},
        last_updated: new Date().toISOString()
    };
}

global.set('sensor_data', sensorData);

// Prüfe ob alle wichtigen Daten vorhanden sind
const hasAllData = entities.every(entity => sensorData[entity]);

if (hasAllData) {
    // Erstelle strukturiertes Datenobjekt
    msg.payload = {
        rct: {
            grid_power: parseFloat(sensorData['sensor.rct_power_storage_grid_power'].state) || 0,
            battery_soc: parseFloat(sensorData['sensor.rct_power_storage_battery_state_of_charge'].state) || 0,
            battery_power: parseFloat(sensorData['sensor.rct_power_storage_battery_power'].state) || 0,
            inverter_power: parseFloat(sensorData['sensor.rct_power_storage_inverter_ac_power'].state) || 0,
            consumer_power: parseFloat(sensorData['sensor.rct_power_storage_consumer_power'].state) || 0
        },
        easee: {
            power: parseFloat(sensorData['sensor.easee_home_power'].state) || 0,
            current: parseFloat(sensorData['sensor.easee_home_maximum_allowed_charge_current'].state) || 0,
            charging: sensorData['binary_sensor.easee_home_charging'].state === 'on'
        },
        zoe: {
            battery: parseFloat(sensorData['sensor.zoe_battery'].state) || 0,
            plug_state: sensorData['sensor.zoe_plug_state'].state,
            charge_state: sensorData['sensor.zoe_charge_state'].state
        },
        timestamp: new Date().toISOString()
    };

    return msg;
}

return null;

const data = msg.payload;

// === v2.0: Lese alle Config-Werte LIVE aus Home Assistant ===
const ha = global.get('homeassistant');
if (!ha || !ha.homeAssistant || !ha.homeAssistant.states) {
    node.warn('[v2.0] Home Assistant States nicht verfügbar!');
    return null;
}
const haStates = ha.homeAssistant.states;

const ladeModus = (haStates['input_select.lade_modus'] || {}).state || 'stoppen';
const socOverride = (haStates['input_boolean.soc_override'] || {}).state === 'on';
const maxChargeCurrent = parseFloat((haStates['input_number.max_charge_current'] || {}).state) || 32;
const minChargeCurrent = parseFloat((haStates['input_number.min_charge_current'] || {}).state) || 7;
const carTargetSoc = parseFloat((haStates['input_number.car_target_soc'] || {}).state) || 80;
const batteryPriority = (haStates['input_boolean.battery_priority'] || {}).state === 'on';
const minBatterySoc = parseFloat((haStates['input_number.min_battery_soc'] || {}).state) || 95;
const phases = parseFloat((haStates['input_number.phases'] || {}).state) || 3;
const preventBatteryDischarge = (haStates['input_boolean.prevent_battery_discharge'] || {}).state === 'on';

// Config für nachfolgende Nodes mitgeben
msg.payload.config = {
    lade_modus: ladeModus,
    soc_override: socOverride,
    max_charge_current: maxChargeCurrent,
    min_charge_current: minChargeCurrent,
    car_target_soc: carTargetSoc,
    battery_priority: batteryPriority,
    min_battery_soc: minBatterySoc,
    phases: phases,
    prevent_battery_discharge: preventBatteryDischarge
};

// === MODUS: STOPPEN ===
if (ladeModus === 'stoppen') {
    msg.payload.control = { action: 'stop', reason: 'Modus: Stoppen', mode: 'stoppen' };
    return msg;
}

// === Prüfe ob Auto angeschlossen ===
const carPluggedIn = data.zoe.plug_state === 'Plugged in' || data.zoe.plug_state === 'plugged';
if (!carPluggedIn) {
    msg.payload.control = { action: 'stop', reason: 'Fahrzeug nicht angeschlossen', mode: 'idle' };
    return msg;
}

// === SOC-Prüfung je nach Modus ===
// Automatik: HARD-LIMIT - NIEMALS überbrückbar!
if (ladeModus === 'automatik') {
    if (data.zoe.battery >= carTargetSoc) {
        msg.payload.control = { action: 'stop', reason: 'Auto-SOC ' + data.zoe.battery + '% >= ' + carTargetSoc + '% (HARD-LIMIT)', mode: 'automatik' };
        return msg;
    }
}
// Manuell + PV-Überschuss: SOC nur wenn Override AUS
if (ladeModus === 'laden' || ladeModus === 'überschuss') {
    if (!socOverride && data.zoe.battery >= carTargetSoc) {
        msg.payload.control = { action: 'stop', reason: 'Auto-SOC ' + data.zoe.battery + '% >= ' + carTargetSoc + '% (SOC-Override: AUS)', mode: ladeModus };
        return msg;
    }
}

// === MODUS: MANUELL (laden) ===
// Direkt mit max_charge_current laden, keine PV-Berechnung nötig
if (ladeModus === 'laden') {
    msg.payload.control = {
        action: 'force_charge',
        reason: 'Manuell laden mit ' + maxChargeCurrent + 'A',
        target_current: maxChargeCurrent,
        mode: 'laden'
    };
    return msg;
}

// === MODI: automatik + überschuss → PV-Überschuss berechnen ===

// Batterie-Priorität prüfen
if (batteryPriority && data.rct.battery_soc < minBatterySoc) {
    msg.payload.control = { action: 'stop', reason: 'Batterie-Priorität: SOC ' + data.rct.battery_soc + '% < ' + minBatterySoc + '%', mode: ladeModus };
    return msg;
}

// Berechne verfügbaren Überschuss
let available_surplus = 0;

if (data.rct.grid_power < 0) {
    // Es wird eingespeist
    available_surplus = Math.abs(data.rct.grid_power);
    // Addiere aktuelle Wallbox-Leistung falls schon am Laden
    if (data.easee.charging && data.easee.power > 0) {
        available_surplus += data.easee.power;
    }
} else {
    // Es wird bezogen
    if (data.easee.charging && data.easee.power > 0) {
        available_surplus = data.easee.power - data.rct.grid_power;
    } else {
        available_surplus = -data.rct.grid_power;
    }
}

// Batterie-Entladungsschutz
if (preventBatteryDischarge && data.rct.battery_power > 0) {
    available_surplus -= data.rct.battery_power;
}

msg.payload.calculated = {
    available_surplus: Math.round(available_surplus),
    grid_power: data.rct.grid_power,
    battery_power: data.rct.battery_power,
    battery_soc: data.rct.battery_soc,
    current_charging_power: data.easee.power
};

return msg;

const data = msg.payload;
const config = data.config;

// === MANUELLES LADEN: Direkt durchreichen ===
if (data.control && data.control.action === 'force_charge') {
    const phases = config.phases;
    msg.payload.control.calculated_power = Math.round(data.control.target_current * 230 * phases);
    return [null, msg, null, null]; // Output 2: Start + Set Current
}

// === STOP bereits gesetzt (SOC-Limit, nicht angeschlossen, etc.) ===
if (data.control && data.control.action === 'stop') {
    return [msg, null, null, null]; // Output 1: Stop
}

// === PV-ÜBERSCHUSS LOGIK (für Modi: automatik + überschuss) ===
const surplus = data.calculated.available_surplus;
const isCharging = data.easee.charging;
const phases = config.phases;
const minCurrent = config.min_charge_current;
const maxCurrent = config.max_charge_current;
const mode = config.lade_modus;

// Berechne Strom aus Überschuss
function calculateCurrent(power_watts) {
    if (phases === 3) {
        return power_watts / (230 * phases);
    }
    return power_watts / 230;
}

function calculatePower(current_ampere) {
    if (phases === 3) {
        return current_ampere * 230 * phases;
    }
    return current_ampere * 230;
}

let targetCurrent = Math.round(calculateCurrent(surplus));
targetCurrent = Math.max(minCurrent, Math.min(maxCurrent, targetCurrent));

let action = 'hold';
let reason = '';

// Genug Überschuss? Mindestens 3600W (3,6kW)
const minStartPower = 3600;

if (surplus >= minStartPower) {
    if (isCharging) {
        action = 'charge';
        reason = mode + ': ' + Math.round(surplus) + 'W -> ' + targetCurrent + 'A';
    } else {
        action = 'start';
        reason = mode + ' Start: ' + Math.round(surplus) + 'W -> ' + targetCurrent + 'A';
    }
} else {
    if (isCharging) {
        action = 'stop';
        reason = mode + ': Überschuss zu gering (' + Math.round(surplus) + 'W < ' + Math.round(minStartPower) + 'W)';
    } else {
        action = 'hold';
        reason = mode + ': Warte auf Überschuss (' + Math.round(surplus) + 'W < ' + Math.round(minStartPower) + 'W)';
    }
}

// === API-Throttling (aus v1.7 beibehalten) ===
const now = Date.now();
const lastSetCurrent = flow.get('last_api_current') || 0;
const lastApiCall = flow.get('last_api_timestamp') || 0;
const timeSinceLastCall = (now - lastApiCall) / 1000;

// Kein API-Call wenn Strom unverändert
if (action === 'charge' && targetCurrent === lastSetCurrent) {
    action = 'hold';
}
// Min. 30s zwischen API-Calls
if (action === 'charge' && timeSinceLastCall < 30 && targetCurrent !== lastSetCurrent) {
    action = 'hold';
}
// Nur signifikante Änderungen (>=1A)
if (action === 'charge' && Math.abs(targetCurrent - lastSetCurrent) < 1) {
    targetCurrent = lastSetCurrent;
    action = 'hold';
}

// Tracking für nächsten Call
if (action === 'charge' || action === 'start') {
    flow.set('last_api_current', targetCurrent);
    flow.set('last_api_timestamp', now);
}

// Control-Message
msg.payload.control = {
    action: action,
    target_current: targetCurrent,
    mode: mode,
    reason: reason,
    calculated_power: Math.round(calculatePower(targetCurrent))
};

// Debug-Logging
if (action !== 'hold') {
    node.warn('═══ PV-Laden v2.0 ═══');
    node.warn('[MODE] ' + mode + ' | SOC-Override: ' + (config.soc_override ? 'AN' : 'AUS'));
    node.warn('[PV] Überschuss: ' + Math.round(surplus) + 'W');
    node.warn('[TGT] ' + targetCurrent + 'A (' + Math.round(calculatePower(targetCurrent)) + 'W)');
    node.warn('[ACT] ' + action + ' | ' + reason);
    node.warn('═════════════════════');
}

// Routing
if (action === 'stop') {
    return [msg, null, null, null]; // Output 1: Stop
} else if (action === 'start') {
    return [null, msg, null, null]; // Output 2: Start
} else if (action === 'charge') {
    return [null, null, msg, null]; // Output 3: Adjust Current
} else {
    return [null, null, null, msg]; // Output 4: Hold/Idle
}

const control = msg.payload.control;
const data = msg.payload;

// Erstelle Log-Eintrag
const logEntry = {
    timestamp: new Date().toISOString(),
    action: control.action,
    mode: control.mode || 'unknown',
    reason: control.reason,
    target_current: control.target_current || 0,
    calculated_power: control.calculated_power || 0,
    available_surplus: data.calculated ? data.calculated.available_surplus : 0,
    battery_soc: data.rct ? data.rct.battery_soc : 0,
    car_soc: data.zoe ? data.zoe.battery : 0
};

// Speichere letzte 100 Log-Einträge
let logs = global.get('charging_logs') || [];
logs.unshift(logEntry);
if (logs.length > 100) logs = logs.slice(0, 100);
global.set('charging_logs', logs);

// Update Status für Dashboard
const status = {
    mode: control.mode || 'unknown',
    action: control.action,
    current_charging: data.easee ? data.easee.charging : false,
    target_current: control.target_current,
    available_surplus: data.calculated ? data.calculated.available_surplus : 0,
    battery_soc: data.rct ? data.rct.battery_soc : 0,
    car_soc: data.zoe ? data.zoe.battery : 0,
    last_update: new Date().toISOString(),
    reason: control.reason
};

global.set('charging_status', status);

msg.payload = logEntry;
return msg;
